import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, uniform, sin, dot, fract } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group, Mesh, PlaneGeometry, Color,
    DirectionalLight, PointLight, AmbientLight,
    Box3, Vector3,
  } = ctx.THREE;

  const COLORS = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10', surface: '#101017', ink: '#16161d',
    paper: '#e8ecf2', accent: '#ff2a38',
  };

  const group = new Group();
  group.userData.handlers = {};
  const timelines = [];
  const primHandles = [];
  const disposables = [];

  // ---------- Backdrop stage (fills frame, engineered vertical gradient + grain) ----------
  const backdropGeo = new PlaneGeometry(24, 15);
  const backdropMat = new MeshBasicNodeMaterial();
  const cTop = uniform(vec3(...new Color('#13131a').toArray()));
  const cBot = uniform(vec3(...new Color('#0b0b10').toArray()));
  const gr = fract(sin(dot(uv(), vec2(12.9898, 78.233))).mul(43758.5453));
  const grain = gr.sub(0.5).mul(0.015);
  backdropMat.colorNode = mix(cBot, cTop, uv().y).add(grain);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- Lights (node-local; illuminate the underline / any PBR) ----------
  const ambient = new AmbientLight(new Color(COLORS.paper), 0.5);
  group.add(ambient);

  const key = new DirectionalLight(new Color(COLORS.paper), 1.1);
  key.position.set(2.5, 3, 4);
  group.add(key);

  const rim = new PointLight(new Color(COLORS.accent), 1.0, 20);
  rim.position.set(-3, -1.5, 2.5);
  group.add(rim);

  // ---------- Text bridging ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findRole = (r) => items.find((i) => i.role === r);
  const captionText = (findRole('caption')?.text ?? 'NOVA ATELIER / CALIBRE PROGRAM').toUpperCase();
  const heroText = findRole('hero')?.text ?? 'TIME, MACHINED.';
  const subheadText = findRole('subhead')?.text ?? 'Every calibre begins as a solid billet.';

  // deterministic fit: scale the created text to a target scene-unit em height,
  // regardless of the atlas px->unit mapping. This kills the giant-blob failure.
  const fitInto = (obj, targetHeight) => {
    obj.updateWorldMatrix(true, true);
    const box = new Box3().setFromObject(obj);
    const size = new Vector3();
    const center = new Vector3();
    box.getSize(size);
    box.getCenter(center);
    const s = size.y > 0.0001 ? targetHeight / size.y : 1;
    obj.scale.setScalar(s);
    obj.position.set(-center.x * s, -center.y * s, 0);
  };

  // ---------- Caption kicker (mono 700, uppercase, letterspaced) ----------
  const captionRaw = ctx.fontAtlas.createText(captionText, {
    fontSize: 64,
    color: COLORS.paper,
    align: 'center',
    letterSpacingPx: 8,
  });
  fitInto(captionRaw, 0.11);
  const captionWrap = new Group();
  captionWrap.add(captionRaw);
  captionWrap.position.set(0, 1.15, 0);
  group.add(captionWrap);

  // ---------- Hero headline ----------
  const heroGroup = new Group();      // weighted-settle target
  heroGroup.position.set(0, 0.4, 0);
  group.add(heroGroup);

  const heroWrap = new Group();       // kinetic-text primitive target
  heroGroup.add(heroWrap);

  const heroRaw = ctx.fontAtlas.createText(heroText, {
    fontSize: 96,
    color: COLORS.paper,
    align: 'center',
  });
  fitInto(heroRaw, 0.62);
  heroWrap.add(heroRaw);

  // ---------- Accent underline rule ----------
  const ulGeo = new PlaneGeometry(2.6, 0.045);
  ulGeo.translate(1.3, 0, 0); // anchor left
  const ulMat = new MeshStandardNodeMaterial();
  ulMat.color = new Color(COLORS.accent);
  ulMat.emissive = new Color(COLORS.accent);
  ulMat.emissiveIntensity = 1.2;
  ulMat.roughness = 0.5;
  ulMat.metalness = 0.2;
  const underline = new Mesh(ulGeo, ulMat);
  underline.position.set(-1.3, -0.05, 0.12);
  underline.scale.x = 0;
  group.add(underline);
  disposables.push(ulGeo, ulMat);

  // ---------- Subhead ----------
  const subheadRaw = ctx.fontAtlas.createText(subheadText, {
    fontSize: 64,
    color: COLORS.paper,
    align: 'center',
  });
  fitInto(subheadRaw, 0.2);
  const subheadWrap = new Group();
  subheadWrap.add(subheadRaw);
  subheadWrap.position.set(0, -0.65, 0);
  group.add(subheadWrap);

  // ---------- Motion ----------
  // caption fade-up
  captionWrap.position.y = 1.15 + 0.2;
  const capTl = gsap.timeline();
  capTl.to(captionWrap.position, { y: 1.15, duration: 0.5, ease: 'power2.out' }, 0.1);
  timelines.push(capTl);

  // hero kinetic entrance via primitive + weighted settle
  heroGroup.scale.setScalar(1.04);
  const heroTl = gsap.timeline();
  heroTl.fromTo(
    heroGroup.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0.6
  );
  // underline draw
  heroTl.to(underline.scale, { x: 1, duration: 0.5, ease: 'power2.out' }, 0.85);
  timelines.push(heroTl);

  // subhead fade-up
  subheadWrap.position.y = -0.65 - 0.2;
  const subTl = gsap.timeline();
  subTl.to(subheadWrap.position, { y: -0.65, duration: 0.5, ease: 'power2.out' }, 1.0);
  timelines.push(subTl);

  // idle: single slow breathing on hero (<=2%)
  const idleTl = gsap.timeline({ delay: 2.2 });
  idleTl.to(heroGroup.scale, {
    x: 1.015, y: 1.015, z: 1.015,
    duration: 4, ease: 'sine.inOut',
    yoyo: true, repeat: -1,
  });
  timelines.push(idleTl);

  // ---------- Apply cinematic primitives ----------
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives?.[p.name];
    if (fn) {
      const target = p.name === 'kinetic-text' ? heroWrap : group;
      const handle = fn(target, p.params ?? {});
      if (handle) primHandles.push(handle);
    }
  }

  // ---------- Cleanup ----------
  group.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const h of primHandles) h?.cleanup?.();
    for (const d of disposables) d?.dispose?.();
    group.traverse((o) => {
      if (o.geometry) o.geometry.dispose?.();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.());
        else o.material.dispose?.();
      }
    });
  };

  return group;
}
